            return True
        path.pop()
        return False

    def find_k_distance_nodes(node, k, block_node, result):
        if node is None or k < 0 or node.val == block_node:
            return
        if k == 0:
            result.append(node.val)
            return
        find_k_distance_nodes(node.left, k - 1, block_node, result)
        find_k_distance_nodes(node.right, k - 1, block_node, result)

